 def table(title,headers,rows,widths):
  nonlocal tn
  tn+=1;small(f'Таблица {tn} — {title}').paragraph_format.keep_with_next=True
  t=doc.add_table(rows=1,cols=len(headers));t.autofit=False
  for col,w in zip(t.columns,widths):col.width=Cm(w)
  for cell,text in zip(t.rows[0].cells,headers):cell.text=str(text)
  t.rows[0]._tr.get_or_add_trPr().append(OxmlElement('w:tblHeader'))
  for cell in t.rows[0].cells:
   fill=OxmlElement('w:shd');fill.set(qn('w:fill'),'EAEAEA');cell._tc.get_or_add_tcPr().append(fill)
  for row in rows:
   for cell,text in zip(t.add_row().cells,row):cell.text=str(text)
  for row in t.rows:
   row._tr.get_or_add_trPr().append(OxmlElement('w:cantSplit'))
   for cell in row.cells:
    mar=OxmlElement('w:tcMar')
    for side,value in [('top',65),('bottom',65),('left',85),('right',85)]:
     e=OxmlElement('w:'+side);e.set(qn('w:w'),str(value));e.set(qn('w:type'),'dxa');mar.append(e)
    cell._tc.get_or_add_tcPr().append(mar)
    for q in cell.paragraphs:
     q.alignment=0;q.paragraph_format.first_line_indent=Cm(0);q.paragraph_format.line_spacing=1.05;q.paragraph_format.space_before=Pt(0);q.paragraph_format.space_after=Pt(3)
